-- DEMONRPG(A!U)[32+64]-V22.01_VI
-- Do not edit this file. Any change breaks the decoder.
local _cphawu = 85
local _jvagvs = 244
local _vmxzsg = 91
local _cgpjdu = ""

local _zqxyuv = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _smquew(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _etthwd(d)
	d = d:gsub("[^" .. _zqxyuv .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_zqxyuv:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ggdxkm = _etthwd(_cgpjdu)
local _qgxfav = { _cphawu, _jvagvs, _vmxzsg }
local _kobvng = {}
for i = 1, #_ggdxkm do
	_kobvng[i] = string.char(_smquew(_ggdxkm:byte(i), _qgxfav[(i - 1) % 3 + 1]))
end

local _zvurab = load or loadstring
local _mjwlrp, _fgcnkt = _zvurab(table.concat(_kobvng), "=w")
if not _mjwlrp then
	gg.alert("Corrupted file: " .. tostring(_fgcnkt))
	os.exit()
end
_mjwlrp()
